/**
 * Device Detection Module
 * Detects and provides detailed information about the user's device and browser
 */

import platform from 'platform';

/**
 * Detect device and browser information
 * @returns {Object} Device information object
 */
export function detectDevice() {
  // Get platform information
  const platformInfo = platform.parse(navigator.userAgent);

  // Detect device type
  const deviceType = detectDeviceType();

  // Get GPU information (if available via WebGL)
  const gpuInfo = detectGPU();

  // Get memory information (if available)
  const memoryInfo = detectMemory();

  // Get screen information
  const screenInfo = {
    width: window.screen.width,
    height: window.screen.height,
    pixelRatio: window.devicePixelRatio || 1,
    colorDepth: window.screen.colorDepth
  };

  // Get CPU cores (if available)
  const cpuCores = navigator.hardwareConcurrency || 'unknown';

  return {
    // Browser information
    browser: {
      name: platformInfo.name || 'unknown',
      version: platformInfo.version || 'unknown',
      layout: platformInfo.layout || 'unknown'
    },
    
    // Operating System information
    os: {
      name: platformInfo.os?.family || 'unknown',
      version: platformInfo.os?.version || 'unknown',
      architecture: platformInfo.os?.architecture || 'unknown'
    },
    
    // Device information
    device: {
      type: deviceType,
      manufacturer: platformInfo.manufacturer || 'unknown',
      model: platformInfo.product || 'unknown',
      cpuCores: cpuCores
    },
    
    // GPU information
    gpu: gpuInfo,
    
    // Memory information
    memory: memoryInfo,
    
    // Screen information
    screen: screenInfo,
    
    // Raw user agent
    userAgent: navigator.userAgent,
    
    // Detection timestamp
    timestamp: new Date().toISOString()
  };
}

/**
 * Detect device type (mobile, tablet, desktop)
 * @returns {string} Device type
 */
function detectDeviceType() {
  const ua = navigator.userAgent.toLowerCase();
  
  // Check for mobile devices
  if (/mobile|android|iphone|ipod|blackberry|iemobile|opera mini/i.test(ua)) {
    return 'mobile';
  }
  
  // Check for tablets
  if (/tablet|ipad|playbook|silk/i.test(ua)) {
    return 'tablet';
  }
  
  // Check for touch support (additional indicator for mobile/tablet)
  if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
    // If touch is supported but not explicitly mobile/tablet, check screen size
    const screenWidth = window.screen.width;
    if (screenWidth < 768) {
      return 'mobile';
    } else if (screenWidth < 1024) {
      return 'tablet';
    }
  }
  
  return 'desktop';
}

/**
 * Detect GPU information via WebGL
 * @returns {Object} GPU information
 */
function detectGPU() {
  try {
    const canvas = document.createElement('canvas');
    const gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
    
    if (!gl) {
      return {
        vendor: 'unknown',
        renderer: 'unknown',
        webglVersion: 'not supported'
      };
    }
    
    const debugInfo = gl.getExtension('WEBGL_debug_renderer_info');
    let vendor = 'unknown';
    let renderer = 'unknown';
    
    if (debugInfo) {
      vendor = gl.getParameter(debugInfo.UNMASKED_VENDOR_WEBGL);
      renderer = gl.getParameter(debugInfo.UNMASKED_RENDERER_WEBGL);
    }
    
    // Check for WebGL2 support
    const gl2 = canvas.getContext('webgl2');
    const webglVersion = gl2 ? 'WebGL 2.0' : 'WebGL 1.0';
    
    return {
      vendor: vendor,
      renderer: renderer,
      webglVersion: webglVersion
    };
  } catch (error) {
    return {
      vendor: 'unknown',
      renderer: 'unknown',
      webglVersion: 'detection failed',
      error: error.message
    };
  }
}

/**
 * Detect memory information (if available)
 * @returns {Object} Memory information
 */
function detectMemory() {
  // Check if memory information is available (Chrome/Edge only)
  if (performance.memory) {
    return {
      jsHeapSizeLimit: performance.memory.jsHeapSizeLimit,
      totalJSHeapSize: performance.memory.totalJSHeapSize,
      usedJSHeapSize: performance.memory.usedJSHeapSize,
      unit: 'bytes'
    };
  }
  
  // Check for deviceMemory (available in some browsers)
  if (navigator.deviceMemory) {
    return {
      deviceMemory: navigator.deviceMemory,
      unit: 'GB'
    };
  }
  
  return {
    available: false,
    note: 'Memory information not available in this browser'
  };
}

/**
 * Get a simplified device summary for logging
 * @param {Object} deviceInfo - Device information object
 * @returns {string} Human-readable device summary
 */
export function getDeviceSummary(deviceInfo) {
  return `${deviceInfo.device.type} - ${deviceInfo.os.name} ${deviceInfo.os.version} - ${deviceInfo.browser.name} ${deviceInfo.browser.version}`;
}

/**
 * Check if device supports required features for face detection
 * @returns {Object} Feature support information
 */
export function checkFeatureSupport() {
  const support = {
    webgl: false,
    webgl2: false,
    wasm: false,
    simd: false,
    camera: false,
    workers: false
  };

  // Check WebGL support
  try {
    const canvas = document.createElement('canvas');
    support.webgl = !!(canvas.getContext('webgl') || canvas.getContext('experimental-webgl'));
    support.webgl2 = !!canvas.getContext('webgl2');
  } catch (e) {
    support.webgl = false;
    support.webgl2 = false;
  }

  // Check WebAssembly support
  support.wasm = typeof WebAssembly === 'object';

  // Check SIMD support
  support.simd = typeof WebAssembly !== 'undefined' && 
                 typeof WebAssembly.validate === 'function';

  // Check camera access
  support.camera = !!(navigator.mediaDevices && navigator.mediaDevices.getUserMedia);

  // Check Web Workers support
  support.workers = typeof Worker !== 'undefined';

  return support;
}

export default detectDevice;

